/**
 * Base64-embedded font bytes for the dr-omnia-book-v1 template.
 * Not read from disk at render time (Vercel's file tracing would need
 * outputFileTracingIncludes for that) and not fetched over the network
 * (fonts.gstatic.com is unreachable from a network-restricted runtime and
 * a runtime fetch reintroduces the exact font-load-timing race the
 * font-readiness invariant exists to eliminate). Source: Google Fonts
 * (Cairo, Noto Naskh Arabic — both OFL), fetched once and vendored here.
 *
 * Noto Naskh Arabic ships an IDENTICAL file for weight 400 and 700 in its
 * Arabic-script subset (confirmed by comparing the served URLs) — there is
 * no genuine bold instance to embed, so only the regular weight is here;
 * "bold" body text relies on the browser's synthetic-bold fallback, which
 * does not affect glyph shaping/joining (that happens at glyph-selection
 * time, before any faux-bold stroke synthesis).
 */

export const CAIRO_BOLD_ARABIC = "";

export const CAIRO_BOLD_LATIN = "";

export const NASKH_REGULAR_ARABIC = "";

export const NASKH_REGULAR_LATIN = "";
